// Helper function to convert text to Title Case
function toTitleCase(str) {
  if (!str) return "UNKNOWN";
  return str.toString().trim().toLowerCase().replace(/\b\w/g, c => c.toUpperCase());
}

const results = [];

// Loop over all 50 incoming items
for (const item of $input.all()) {
  let rawResponse = item.json.text || item.json.response || JSON.stringify(item.json);

  // Strip out markdown code fences
  rawResponse = rawResponse.replace(/```json/gi, '').replace(/```/g, '').trim();

  let row = {};
  try {
    row = JSON.parse(rawResponse);
  } catch (e) {
    row = item.json;
  }

  // Name: Title Case
  const cleanName = toTitleCase(row.Name || "");

  // Email: Must contain '@' and ('.com' or '.in')
  const rawEmail = (row.Email || "").toString().trim().toLowerCase();
  const isValidEmail = rawEmail.includes('@') && (rawEmail.endsWith('.com') || rawEmail.endsWith('.in'));
  const cleanEmail = isValidEmail ? rawEmail : "INVALID_EMAIL";

  // Phone: Must be at least 10 digits
  const digitsOnly = (row.Phone || "").toString().replace(/\D/g, '');
  const cleanPhone = digitsOnly.length >= 10 ? digitsOnly : "MISSING";

  // Course: Only "Python", "Machine Learning", or "Data Science"
  let cleanCourse = (row.Course || "").toString().trim();
  const validCourses = ["Python", "Machine Learning", "Data Science"];
  const matchedCourse = validCourses.find(c => c.toLowerCase() === cleanCourse.toLowerCase());
  cleanCourse = matchedCourse || "Python";

  // Fee_Paid: Boolean (true / false)
  let cleanFee = false;
  if (typeof row.Fee_Paid === 'boolean') {
    cleanFee = row.Fee_Paid;
  } else if (typeof row.Fee_Paid === 'string') {
    cleanFee = ['yes', 'true', '1'].includes(row.Fee_Paid.trim().toLowerCase());
  }

  // City: Title Case, empty = UNKNOWN
  let cleanCity = toTitleCase(row.City || "");
  if (!cleanCity || cleanCity.toLowerCase() === 'unknown') {
    cleanCity = "UNKNOWN";
  }

  // Enrolled_Date: YYYY-MM-DD
  let cleanDate = (row.Enrolled_Date || "").toString().trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(cleanDate)) {
    const d = new Date(cleanDate);
    cleanDate = !isNaN(d.getTime()) ? d.toISOString().split('T')[0] : "2025-01-01";
  }

  results.push({
    json: {
      Student_ID: row.Student_ID || "STU_UNKNOWN",
      Name: cleanName,
      Email: cleanEmail,
      Phone: cleanPhone,
      Course: cleanCourse,
      Fee_Paid: cleanFee,
      City: cleanCity,
      Enrolled_Date: cleanDate
    }
  });
}

return results;
